        Check(new DateTime(2026,9,20).ToString("MMM d, yyyy",Localization.Culture("en"))=="Sep 20, 2026","English dates ignore Windows regional language");
        var fixture=J.Obj("account",J.Obj("email","a@example.invalid","planType","prolite"),"result",J.Obj("rateLimitsByLimitId",J.Obj("codex",J.Obj("primary",J.Obj("usedPercent",23,"windowDurationMins",10080,"resetsAt",20000)),"reserve",J.Obj("primary",J.Obj("usedPercent",99,"windowDurationMins",10080,"resetsAt",20000)))));
        var a=J.Get(fixture,"account");var s=Model.Normalize(a,fixture["result"],1000);var windows=J.Items(s["windows"]).ToArray();Check(windows.Length==2,"All quota pools preserved");Check(J.N(windows[0],"minutes")==10080,"Weekly primary correctly identified");Check(J.N(windows[0],"remaining")==77,"Remaining calculated");Check(J.N(Model.Selected(s,"auto",1000),"remaining")==77,"Reserve excluded from ring");Check(J.N(Model.Selected(s,"five",1000),"remaining")==77,"Pinned missing window falls back");Check(Model.Plan("prolite")=="Pro","Plan alias");Check(Model.Plan("custom")=="custom","Unknown plan retained");Check(J.Get(J.Get(s,"resets"),"count")==null,"Missing reset count stays unknown");
        var zero=Model.Normalize(a,J.Obj("rateLimits",J.Obj("primary",J.Obj("usedPercent",100,"windowDurationMins",300)),"rateLimitResetCredits",J.Obj("availableCount",0)),1000);Check(J.N(Model.Selected(zero,"auto",1000),"remaining")==0,"Actual zero preserved");Check(J.N(J.Get(zero,"resets"),"count",-1)==0,"Zero reset preserved");Check(Model.Cache(s,"other",2000)==null,"Cache account boundary");Check(Model.Cache(s,J.S(s,"identity"),86401001)==null,"Cache expires");Check(Model.Cache(s,J.S(s,"identity"),30000000)==null,"Expired quota removed");
        var u=Model.Usage(J.Obj("dailyUsageBuckets",new[]{J.Obj("startDate","2026-09-18","tokens",0),J.Obj("startDate","2026-09-19","tokens",10),J.Obj("startDate","2026-09-19","tokens",10),J.Obj("startDate","2026-09-17","tokens",12),J.Obj("startDate","2026-09-17","tokens",13),J.Obj("startDate","2026-02-30","tokens",2),J.Obj("startDate","2026-09-16","tokens",-1)}),1000);
        Check(J.Items(u["days"]).Count()==2,"Duplicate/conflicting/invalid dates excluded");Check(J.B(u,"incomplete"),"Partial data labeled");var days=Model.Series(u,7,new DateTime(2026,9,20));Check(days.Count==7&&J.Get(days[6],"tokens")==null,"Missing days remain null");Check(J.N(days[4],"tokens",-1)==0,"Zero differs from missing day");Check(J.S(days[0],"date")=="2026-09-14","Ascending calendar range");Check(Model.Series(u,30,new DateTime(2026,3,1))[0]["date"].ToString()=="2026-01-31","Month boundary");
        var prefs=Model.Settings(J.Obj("mainSize",J.Obj("width",1,"height",9000),"accentColor","#AB12EF","language","bad","membership",J.Obj(J.S(s,"identity"),J.Obj("date","2026-02-30","kind","expiry"))));Check(J.N(prefs["mainSize"],"width")==320&&J.N(prefs["mainSize"],"height")==1400,"Saved window constraints");Check(J.S(prefs,"accentColor")=="#ab12ef"&&J.S(prefs,"language")=="zh","Settings sanitization");Check(J.Map(prefs["membership"]).Count==0,"Invalid membership date discarded");Check(Model.Identity(a)!=Model.Identity(J.Obj("email","b@example.invalid")),"Identity isolation");
        string folder=Path.Combine(Program.QaDirectory,"test-storage");var store=new Store(folder);store.Write("settings",prefs);store.Write("settings",Model.Settings(store.Read("settings")));Check(J.S(store.Read("settings"),"accentColor")=="#ab12ef","Atomic settings round trip");
        TestRpc().GetAwaiter().GetResult();File.WriteAllText(Path.Combine(Program.QaDirectory,"self-test.json"),J.Json(J.Obj("passed",checks,"failed",0)));
