    static async Task TestRpc(){string previous=Environment.GetEnvironmentVariable("CODEX_GLASS_CODEX_PATH");string fake=Environment.GetEnvironmentVariable("CODEX_GLASS_TEST_RPC");Environment.SetEnvironmentVariable("CODEX_GLASS_CODEX_PATH",Assembly.GetExecutingAssembly().Location);Environment.SetEnvironmentVariable("CODEX_GLASS_TEST_RPC","1");try{using(var rpc=new Rpc()){var results=await Task.WhenAll(rpc.Call("account/read"),rpc.Call("account/rateLimits/read"));Check(J.S(J.Get(results[0],"account"),"type")=="chatgpt","RPC handshake and correlation");Check(J.Get(results[1],"rateLimits")!=null,"Concurrent response correlation");int child=rpc.ChildId;Check(child>0,"Helper started");rpc.Stop();await Task.Delay(100);Check(rpc.ChildId==0,"Helper is released after read");bool gone;try{gone=Process.GetProcessById(child).HasExited;}catch{gone=true;}Check(gone,"Helper process actually exits");var again=await rpc.Call("account/read");Check(J.S(J.Get(again,"account"),"type")=="chatgpt","Helper restarts on demand");bool rejected=false;try{await rpc.Call("test/eof");}catch{rejected=true;}Check(rejected&&rpc.ChildId==0,"EOF rejects pending call without busy loop");await rpc.Call("account/read");var held=new[]{rpc.Call("test/hold"),rpc.Call("test/hold"),rpc.Call("test/hold")};await Task.Delay(50);rpc.Stop();foreach(var request in held){bool canceled=false;try{await request;}catch{canceled=true;}Check(canceled,"Stopping helper rejects each concurrent pending call");}Check(rpc.ChildId==0,"Stopped helper stays released");}}finally{Environment.SetEnvironmentVariable("CODEX_GLASS_CODEX_PATH",previous);Environment.SetEnvironmentVariable("CODEX_GLASS_TEST_RPC",fake);}}
    public static void FakeRpc(){string line;while((line=Console.ReadLine())!=null){var m=J.Parse(line);string method=J.S(m,"method");if(method=="test/eof")return;if(method=="test/hold")continue;if(J.Get(m,"id")==null)continue;object result=method=="account/read"?J.Obj("account",J.Obj("type","chatgpt","email","fixture@example.invalid")):method=="account/rateLimits/read"?J.Obj("rateLimits",J.Obj("primary",J.Obj("usedPercent",25,"windowDurationMins",10080))):new D();Console.WriteLine(J.Json(J.Obj("id",J.Get(m,"id"),"result",result)));}}
}
