            var menu=LanguageMenu(button);NativeTests.Check(menu.Items.Count==3,"Language popup has three choices");
            NativeTests.Check(menu.Items.Cast<MenuItem>().Count(i=>i.IsChecked)==1,"Language popup marks one current language");
            menu.IsOpen=true;await Pause();
            var image=new RenderTargetBitmap((int)Math.Ceiling(menu.ActualWidth),(int)Math.Ceiling(menu.ActualHeight),96,96,PixelFormats.Pbgra32);image.Render(menu);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(image));using(var file=File.Create(Path.Combine(Program.QaDirectory,"language-menu.png")))png.Save(file);
            var item=(MenuItem)menu.Items[Array.IndexOf(Localization.Codes,code)];item.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));menu.IsOpen=false;await Pause();
            NativeTests.Check(J.S(Service.Store.Read("settings"),"language")==code,"Menu language persists: "+code);
            NativeTests.Check(Descendants<TextBlock>(this).Any(t=>t.Text==T("title")),"Overview translated: "+code);
