        foreach(var point in new[]{new Point(5,28),new Point(header.ActualWidth/2,5),new Point(header.ActualWidth-5,28)}){
            var hit=InputHitTest(header.TranslatePoint(point,this)) as DependencyObject;
            NativeTests.Check(HeaderDragTarget(hit,header),"Title bar blank space accepts dragging");
        }
        foreach(var element in Descendants<Image>(header).Cast<FrameworkElement>().Concat(Descendants<TextBlock>(header).Where(t=>t.Text=="Codex Glass"))){
            var hit=InputHitTest(element.TranslatePoint(new Point(element.ActualWidth/2,element.ActualHeight/2),this)) as DependencyObject;
            NativeTests.Check(HeaderDragTarget(hit,header),"Logo/title accepts dragging");
        }
        foreach(var button in Descendants<Button>(header)){
            var hit=InputHitTest(button.TranslatePoint(new Point(button.ActualWidth/2,button.ActualHeight/2),this)) as DependencyObject;
            NativeTests.Check(!HeaderDragTarget(hit,header),"Header button stays clickable");
        }
        var oldContent=Content;moving=true;Render();NativeTests.Check(Content==oldContent&&renderAfterMove,"Refresh deferred during window drag");moving=false;renderAfterMove=false;Render();
    }
